
// Script buffer constants
const DEF_LIMIT = 5   // default buffer length
const BUF_INC = 5     // buffer increment for time series

// Function definition regex patterns for script parsing
// FDEFS: Basic function matching (non-greedy, global, multi-line, case-insensitive)
const FDEFS = /(function |)([$A-Z_][0-9A-Z_$\.]*)[\s]*?\((.*?)\)/gmi
// FDEFS1: Single match with trailing whitespace (non-global)
const FDEFS1 = /(function |)([$A-Z_][0-9A-Z_$\.]*)[\s]*?\((.*?\s*)\)/mi
// FDEFS2: Multi-line with dotall for spanning across lines
const FDEFS2 = /(function |)([$A-Z_][0-9A-Z_$\.]*)[\s]*?\((.*\s*)\)/gmis
// SBRACKETS: Array bracket access pattern
const SBRACKETS = /([$A-Z_][0-9A-Z_$\.]*)[\s]*?\[([^"^\[^\]]+?)\]/gmi
// TFSTR: Timeframe string pattern (e.g., "15m", "1h")
const TFSTR = /(\d+)(\w*)/gm

const SECOND = 1000
const MINUTE = SECOND * 60
const MINUTE3 = MINUTE * 3
const MINUTE5 = MINUTE * 5
const MINUTE15 = MINUTE * 15
const MINUTE30 = MINUTE * 30
const HOUR = MINUTE * 60
const HOUR4 = HOUR * 4
const HOUR12 = HOUR * 12
const DAY = HOUR * 24
const WEEK = DAY * 7
const MONTH = WEEK * 4
const YEAR = DAY * 365

const MONTHMAP = [
    "Jan", "Feb", "Mar", "Apr",
    "May", "Jun","Jul", "Aug",
    "Sep", "Oct","Nov", "Dec"
]

// Grid time steps (ascending order — required by nearest_a() binary search)
const TIMESCALES = [
    MINUTE, MINUTE * 2, MINUTE5, MINUTE * 10, MINUTE15, MINUTE30,
    HOUR, HOUR * 1.5, HOUR * 3, HOUR * 6, HOUR * 12,
    DAY, DAY * 2, DAY * 3, DAY * 5, DAY * 7, DAY * 10, DAY * 15,
    MONTH, MONTH * 2, MONTH * 3, MONTH * 4, MONTH * 6,
    YEAR, YEAR * 2, YEAR * 3, YEAR * 5, YEAR * 10
]

// Grid $ steps
const $SCALES = [0.05, 0.1, 0.2, 0.25, 0.5, 0.8, 1, 2, 5]

// Default overlay color palette
const OVERLAY_COLORS = [
    '#42b28a', '#5691ce', '#612ff9',
    '#d50b90', '#ff2316'
]

const ChartConfig = {
    SBMIN: 60,       // Minimal sidebar px
    SBMAX: Infinity, // Max sidebar, px
    TOOLBAR: 57,     // Toolbar width px
    RIGHTBAR: 250,   // Right panel width px
    TB_ICON: 25,     // Toolbar icon size px
    TB_ITEM_M: 6,    // Toolbar item margin px
    TB_ICON_BRI: 1,  // Toolbar icon brightness
    TB_ICON_HOLD: 420, // ms, wait to expand
    TB_BORDER: 1,    // Toolbar border px
    TB_B_STYLE: 'dotted', // Toolbar border style
    TOOL_COLL: 7,    // Tool collision threshold
    EXPAND: 0.15,    // %/100 of range
    CANDLEW: 0.6,    // %/100 of step
    GRIDX: 100,      // px
    GRIDY: 47,       // px
    BOTBAR: 28,      // px
    PANHEIGHT: 22,   // px
    DEFAULT_LEN: 50, // candles
    MINIMUM_LEN: 5,  // candles,
    MIN_ZOOM: 25,    // candles
    MAX_ZOOM: 1000,  // candles,
    VOLSCALE: 0.15,  // %/100 of height
    UX_OPACITY: 0.9, // Ux background opacity
    ZOOM_MODE: 'tv', // 'tv' or 'tl'
    L_BTN_SIZE: 21,  // Legend Button size, px
    L_BTN_MARGIN: '-6px 0 -6px 0', // css margin
    SCROLL_WHEEL: 'prevent', // 'pass', 'click'
}

ChartConfig.FONT =
    `11px -apple-system,BlinkMacSystemFont,
    Segoe UI,Roboto,Oxygen,Ubuntu,Cantarell,
    Fira Sans,Droid Sans,Helvetica Neue,
    sans-serif`

const IB_TF_WARN =
    `When using IB mode you should specify ` +
    `timeframe ('tf' filed in 'chart' object),` +
    `otherwise you can get an unexpected behaviour`

const MAP_UNIT = {
  "1s": SECOND,
  "5s": SECOND * 5,
  "10s": SECOND * 10,
  "20s": SECOND * 20,
  "30s": SECOND * 30,
  "1m": MINUTE,
  "3m": MINUTE3,
  "5m": MINUTE5,
  "15m": MINUTE15,
  "30m": MINUTE30,
  // Uppercase hour formats
  "1H": HOUR,
  "2H": HOUR * 2,
  "3H": HOUR * 3,
  "4H": HOUR4,
  "6H": HOUR * 6,
  "8H": HOUR * 8,
  "12H": HOUR12,
  // Lowercase hour formats
  "1h": HOUR,
  "2h": HOUR * 2,
  "3h": HOUR * 3,
  "4h": HOUR4,
  "6h": HOUR * 6,
  "8h": HOUR * 8,
  "12h": HOUR12,
  // Day/Week/Month/Year (both cases)
  "1D": DAY,
  "1d": DAY,
  "1W": WEEK,
  "1w": WEEK,
  "1M": MONTH,
  "1Y": YEAR
}

export default {
    DEF_LIMIT,
    BUF_INC,
    FDEFS,
    FDEFS1,
    FDEFS2,
    SBRACKETS,
    TFSTR,
    SECOND: SECOND,
    MINUTE: MINUTE,
    MINUTE5: MINUTE5,
    MINUTE15: MINUTE15,
    MINUTE30: MINUTE30,
    HOUR: HOUR,
    HOUR4: HOUR4,
    DAY: DAY,
    WEEK: WEEK,
    MONTH: MONTH,
    YEAR: YEAR,
    MONTHMAP: MONTHMAP,
    TIMESCALES: TIMESCALES,
    $SCALES: $SCALES,
    ChartConfig: ChartConfig,
    map_unit: MAP_UNIT,
    IB_TF_WARN,
    OVERLAY_COLORS
}
